  registerR11Validation(CMS);
  const baselines = {"R02":{"route":{"id":"R02","title":"О перинатальном центре","url":"/about/","type":"T2","adapter":"numbered-lines","sourcePath":"src/data/sources/center.json","sourceEditorialPath":"content/sources/center.json","editorialPath":"content/editable/r02.json","enabled":true},"source":{"code":"R03","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.b2p9krnnyo2m","primaryDocumentId":"1qnuHs4lNhtkCPoR9fmD5ffaHnrj1HURvZtPkis0C360","status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","lines":[{"number":1,"startIndex":340,"text":"Перинатальный центр Пушкино: пространство уверенного материнства и высоких технологий"},{"number":2,"startIndex":426,"text":"Перинатальный центр Пушкино – это уникальное место, где вековые традиции акушерства сочетаются с современными технологиями экспертного уровня. Здесь дарят жизнь с заботой о маме и малыше, независимо от сложности клинической ситуации и места вашего проживания."},{"number":3,"startIndex":686,"text":"Роды по ОМС и по контракту: доступность и выбор"},{"number":4,"startIndex":734,"text":"✔️ Роды по ОМС"},{"number":5,"startIndex":749,"text":"Любая женщина, независимо от города и региона проживания, может выбрать наш центр для рождения малыша. Для этого не нужны согласования или направления. Вы просто приезжаете к нам с началом родовой деятельности."},{"number":6,"startIndex":960,"text":"✔️ Роды «по контракту»"},{"number":7,"startIndex":983,"text":"Для тех, кому важно ведение родов персональным доктором, комфортная послеродовая индивидуальная палата и расширенный спектр услуг, мы разработали удобные программы контрактов. Ознакомиться с условиями и выбрать подходящий вариант можно по ссылке: "},{"number":8,"startIndex":1231,"text":"Партнерские роды"},{"number":9,"startIndex":1248,"text":"В нашем центре активно поддерживается практика партнерских родов, которые доступны всем – как по ОМС, так и по контракту. Мы понимаем, как важна поддержка в этот ответственный момент."},{"number":10,"startIndex":1432,"text":"✔️Кто может быть партнером: супруг, близкий родственник или любой человек, которому вы доверяете."},{"number":11,"startIndex":1530,"text":"✔️Поддержка профессионалов: мы приветствуем присутствие профессиональной помощницы – доулы."},{"number":12,"startIndex":1622,"text":"✔️Упрощенный допуск: для присутствия на родах требуется только заключение флюорографии (или рентгена ОГК) сроком не более 1 года. "},{"number":13,"startIndex":1753,"text":"✔️Кесарево сечение с партнером."},{"number":14,"startIndex":1785,"text":"Мы поддерживаем партнерские роды даже при операции кесарева сечения (в присутствии супруга или доулы). В этом случае «золотой час» (первые минуты после рождения) реализуется «на папе», обеспечивая тактильный контакт и эмоциональную связь."},{"number":15,"startIndex":2024,"text":"📍Никаких дополнительных справок, согласований и разрешений!"},{"number":16,"startIndex":2085,"text":"Оснащение экспертного уровня: Безопасность 24/7"},{"number":17,"startIndex":2133,"text":"Все отделения Перинатального центра оснащены оборудованием экспертного класса. Это значит, что здесь вы получите любую необходимую помощь, включая высокотехнологичную."},{"number":18,"startIndex":2301,"text":"✔️Каждый родильный зал оборудован средствами для экстренной помощи маме и малышу"},{"number":19,"startIndex":2382,"text":"✔️Взрослая и детская реанимации укомплектованы аппаратами последнего поколения. Ваше здоровье и безопасность – под надежным контролем."},{"number":20,"startIndex":2517,"text":"Отделения взрослой и детской реанимации"},{"number":21,"startIndex":2557,"text":"✔️Взрослая реанимация оказывает помощь беременным для благополучного донашивания, а также женщинам после оперативных родов."},{"number":22,"startIndex":2681,"text":"✔️Детская реанимация (ОРИТН) – наша гордость и уникальная практика."},{"number":23,"startIndex":2749,"text":"Помимо оснащения для помощи новорожденным с различными патологиями и недоношенным детям, здесь организовано совместное круглосуточное пребывание мамы и малыша. "},{"number":24,"startIndex":2910,"text":"Что это значит для вас?"},{"number":25,"startIndex":2934,"text":"✔️мама находится с ребёнком круглосуточно – не просто навещает, а остаётся рядом;"},{"number":26,"startIndex":3016,"text":"✔️участвует в уходе вместе с врачами и медсёстрами;"},{"number":27,"startIndex":3068,"text":"✔️созданы все условия для поддержки и сохранения грудного вскармливания."},{"number":28,"startIndex":3141,"text":"Специалисты высокой квалификации: опыт акушерства длиною в век"},{"number":29,"startIndex":3204,"text":"Истории нашего роддома более 100 лет. Начав путь в 1925 году с одной палаты на 3 койки, сегодня мы – современный Перинатальный центр. За плечами наших врачей - колоссальный опыт клинической практики."},{"number":30,"startIndex":3404,"text":"✔️Акушеры-гинекологи: ведут беременности любой сложности, требующие особой квалификации и индивидуального подхода. Владеют мастерством ведения физиологических и сложных родов (тазовое предлежание, рубец на матке, многоплодная беременность). Операции кесарева сечения проводятся на высочайшем уровне."},{"number":31,"startIndex":3704,"text":"✔️Неонатологи: команда специалистов трех отделений (физиологии, реанимации и патологии) бережно наблюдает самых маленьких пациентов, оказывая полный спектр медицинской помощи."},{"number":32,"startIndex":3880,"text":"✔️Акушерки: наши акушерки это верные помощницы в родах и в послеродовом периоде. Именно благодаря мастерству и опыту наших акушерок ваши малыши появляются на свет максимально бережно и физиологично."},{"number":33,"startIndex":4079,"text":"✔️Послеродовое отделение: врачи внимательно следят за восстановлением женщины, обеспечивая комфорт и безопасность."},{"number":34,"startIndex":4194,"text":"Поддержка доул и консультантов по ГВ: забота без границ"},{"number":35,"startIndex":4250,"text":"Мы убеждены, что роды – это не только медицинский процесс, но и важнейший эмоциональный опыт. "},{"number":36,"startIndex":4345,"text":"Чтобы обеспечить полный цикл заботы, мы поддерживаем сотрудничество с помогающими специалистами:"},{"number":37,"startIndex":4442,"text":"✔️доулы: помогут вам прожить роды максимально спокойно, окружат заботой и подскажут, как сделать процесс комфортным на каждом из этапов родв."},{"number":38,"startIndex":4584,"text":"✔️консультанты по грудному вскармливанию: станут вашими верными помощниками в вопросах налаживания ГВ "},{"number":39,"startIndex":4687,"text":" Перинатальный центр Пушкино – это:"},{"number":40,"startIndex":4723,"text":"✔️свобода выбора: роды по ОМС или контракт;"},{"number":41,"startIndex":4767,"text":"✔️ поддержка близких рядом;"},{"number":42,"startIndex":4795,"text":"✔️ современное оснащение и высокотехнологичная помощь;"},{"number":43,"startIndex":4850,"text":"✔️ уникальная возможность совместного пребывания мамы и малыша  в реанимации;"},{"number":44,"startIndex":4928,"text":"✔️ команда опытных врачей и заботливый персонал;"},{"number":45,"startIndex":4977,"text":"✔️ эмоциональная и практическая поддержка на всех этапах."},{"number":46,"startIndex":5035,"text":"Мы создаем пространство, где современная медицина работает в тандеме с душевной поддержкой."},{"number":47,"startIndex":5127,"text":"Доверяя нам самое важное – рождение вашего малыша, вы создаете начало счастливой семейной истории!"}]}},"R04":{"code":"R04","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.8x38frjdb1l","primaryDocumentId":"1j8aWe1HP9F0_MMwRXKrbsgRixvXpw9afC9CoJZu-DSw","status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","lines":[{"number":1,"startIndex":362,"text":"В 2026-м году Перинатальный центр Пушкинской клинической больницы им. проф. В.Н. Розанова отмечает свое 10-летие. Однако история родовспоможения на Пушкинской земле насчитывает уже более ста лет."},{"number":2,"startIndex":558,"text":"📜 1913-1930: с чего всё начиналось"},{"number":3,"startIndex":594,"text":"В 1913 году на арендованном дачном участке открылась первая земская амбулатория. Год спустя заработал стационар на 10 коек."},{"number":4,"startIndex":718,"text":"Акушерское отделение долгое время состояло всего из двух коек в хирургии, позже их число увеличили до пяти. Отделение располагалось в деревянном здании бывшей дачи. Кроватей Рахманова не было, стены были оклеены обоями, а родовая комната покрашена клеевой краской. Зато подготовке кадров уделяли серьёзное внимание - при больнице работала фельдшерско-акушерская школа, выпустившая за три года 226 специалистов."},{"number":5,"startIndex":1129,"text":"📜 1930-1960: становление и признание"},{"number":6,"startIndex":1167,"text":"В 1930 году главврачом и заведующим родильным отделением назначили Михаила Ткаченко. Провели реконструкцию: появились детская палата, изолятор и родовая, стены оштукатурили. Отделение выросло до 15 коек."},{"number":7,"startIndex":1371,"text":"Результат не заставил ждать: если в 1930 году приняли 200 родов, то в 1931-м - уже 400. В 1936 году отделение перевели в хирургический корпус, увеличив до 50 коек."},{"number":8,"startIndex":1535,"text":"С 1937 по 1941 год Пушкинское родильное отделение служило официальной учебной базой для врачей-акушеров Московской области."},{"number":9,"startIndex":1659,"text":"📜 1964-2016: свой дом на 60 коек"},{"number":10,"startIndex":1693,"text":"В 1964 году для родильного отделения построили отдельное двухэтажное здание на 60 коек. Здесь работали легендарные заведующие: Ефремова, Крапалина, Филиппас, Кублицкая, Емельянова, Панфилова. Этот роддом принимал рожениц больше полувека - вплоть до 2016 года."},{"number":11,"startIndex":1953,"text":"📜 2016: рождение нового центра"},{"number":12,"startIndex":1985,"text":"20 мая 2016 года открылся новый родильный дом на 110 мест. Уже в первые дни здесь приняли около 30 родов."},{"number":13,"startIndex":2091,"text":"10 лет работы: подведем итоги"},{"number":14,"startIndex":2121,"text":"За десятилетие в центре принято около 25 тысяч родов. Среди них более 200 двоен и около 300 родов после ЭКО."},{"number":15,"startIndex":2230,"text":"Десятки малышей с весом менее 1000 граммов и еще больше весом до 1500 граммов получили свой шанс на жизнь и благополучное будущее. Немало в истории центра и самых «крошечных историй», когда малыши весом менее (!) 500 грамм были спасены и выхожены, благодаря высочайшему профессионализму и чуткости наших специалистов."},{"number":16,"startIndex":2548,"text":"Отделение реанимации новорождённых - место, где реализуется уникальная практика совместного пребывания матери и ребёнка. За 10 лет здесь получили помощь примерно 3,5 тысячи новорождённых, из них почти 1800 недоношенных."},{"number":17,"startIndex":2768,"text":"Признание: победы и заслуженная награда"},{"number":18,"startIndex":2808,"text":"🔸В 2019 году Пушкинский родильный дом признали лучшим в Московской области. "},{"number":19,"startIndex":2886,"text":"🔸В 2020 году он вошёл в топ-10 государственных клиник региона по версии премии «ПРОДОКТОРОВ»."},{"number":20,"startIndex":2981,"text":"🔸А в декабре 2025 года весь коллектив Перинатального центра был удостоен Почётной грамоты Министерства здравоохранения Московской области. Награда вручена «за добросовестный труд в области здравоохранения, высокий профессионализм и достигнутые успехи в медицинском обслуживании детского населения Московской области»."},{"number":21,"startIndex":3300,"text":"Эта грамота - закономерный итог года, посвящённого труду, росту и заботе о жизни. Она принадлежит каждому, кто встречает новую жизнь, поддерживает маму, выхаживает малыша и создаёт ту самую атмосферу доверия."},{"number":22,"startIndex":3509,"text":"Вековые традиции - современные возможности"},{"number":23,"startIndex":3552,"text":"Но главное не награды. Главное - что больше века назад первые роды в Пушкино принимали в деревянных дачах с обоями на стенах, а сегодня - в современном центре, где есть всё для безопасности мамы и ребёнка. И за этими достижениями - больше ста лет непрерывной истории, десятки поколений врачей, акушерок и сотни тысяч новых жизней."}]},"R09":{"route":{"id":"R09","title":"Приемное отделение","url":"/departments/admission/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/department-admission.json","sourceEditorialPath":"content/pages/r09.json","editorialPath":"content/editable/r09.json","enabled":true},"source":{"code":"R09","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.kkwnyk10s206","originalUrl":"https://docs.google.com/document/d/1rT_pHWOQV8Wg6Zz8LSe78gdC9wE0qN6vqYHhaDVg0vs/edit","paragraphCount":43,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. List markers retained.","review":"Arrival for birth and planned pregnancy-pathology admission remain separate authored sections.","lines":[{"number":1,"startIndex":309,"text":"Самая первая «точка на карте», с которой начинается ваш путь в Перинатальном центре Пушкино -  это приёмное отделение."},{"number":2,"startIndex":428,"text":"Именно сюда вы приедете, когда начнутся роды. Именно сюда - по направлению из женской консультации. И именно сюда - чтобы сдать глюкозо-толерантный тест или лечь «на сохранение»."},{"number":3,"startIndex":607,"text":"Но давайте по порядку. Чтобы вы знали, что вас ждёт, и ничего не пропустили."},{"number":4,"startIndex":684,"text":"✨ Кого и когда принимают"},{"number":5,"startIndex":709,"text":"Приёмное отделение работает круглосуточно, без выходных и праздников. Все 365 дней в году. Роды не спрашивают, какой сегодня день недели 🤷‍♀️"},{"number":6,"startIndex":852,"text":"По каким вопросам к нам можно обратиться:"},{"number":7,"startIndex":894,"text":"✅На роды - в любое время дня и ночи. Схватки, излитие вод, кровотечение - приезжайте сразу. Без записи, без очереди."},{"number":8,"startIndex":1011,"text":"✅На плановую госпитализацию в отделение патологии беременных - по направлению лечащего врача. "},{"number":9,"startIndex":1106,"text":"✨У нас есть"},{"number":10,"startIndex":1118,"text":"✅ Дневной стационар - госпитализация по понедельникам и вторникам (для глюкозо-толерантного теста, резус-иммунизации и других обследований)"},{"number":11,"startIndex":1258,"text":"✅ Круглосуточный стационар - госпитализация с понедельника по пятницу плановая, в выходные дни оказание экстренной медпомощи."},{"number":12,"startIndex":1384,"text":"💕 На роды по контракту или по ОМС - разницы для приёмного отделения. Всех встречаем одинаково, всех оформляем по стандарту."},{"number":13,"startIndex":1509,"text":"✨ Если вы с партнёром"},{"number":14,"startIndex":1531,"text":"Партнёрские роды у нас очень поддерживаются. И ваш сопровождающий (муж, подруга, доула) проходит через приёмное отделение вместе с вами."},{"number":15,"startIndex":1668,"text":"Что нужно знать партнёру:"},{"number":16,"startIndex":1694,"text":"✅ С собой - сменная домашняя одежда и обувь. Это обязательное требование для входа в родовое отделение."},{"number":17,"startIndex":1798,"text":"✅ Из анализов - флюорография сроком не более 12 месяцев. Позаботьтесь об этом заранее. Если нет свежей флюорографии, к сожалению, в родовой блок не пустят."},{"number":18,"startIndex":1954,"text":"✅ В приёмном отделении акушерка покажет, где можно переодеться и подготовиться."},{"number":19,"startIndex":2034,"text":"✨ Что происходит при оформлении на роды"},{"number":20,"startIndex":2074,"text":"✅Вас встречает акушерка приёмного отделения. Проверяет документы: паспорт, обменную карту, полис и т.д."},{"number":21,"startIndex":2178,"text":"✅Заполнение документов - это обязательный этап. "},{"number":22,"startIndex":2227,"text":"Вас попросят заполнить:"},{"number":23,"startIndex":2251,"text":"🔸Согласие на обработку персональных данных"},{"number":24,"startIndex":2295,"text":"🔸Информированное согласие на проведение обследования на ВИЧ-инфекцию"},{"number":25,"startIndex":2365,"text":"🔸Информированное добровольное согласие на медицинское вмешательство (сбор вашего анамнеза, взвешивание, КТГ, осмотр на кресле - это все сюда)"},{"number":26,"startIndex":2508,"text":"✅Далее осмотр в смотровом кабинете. Врач оценит: "},{"number":27,"startIndex":2558,"text":"🔸раскрытие шейки матки"},{"number":28,"startIndex":2582,"text":"🔸состояние плода (сердцебиение, шевеления)"},{"number":29,"startIndex":2626,"text":"🔸общее состояние мамы (давление, пульс, температура)"},{"number":30,"startIndex":2680,"text":"🔸КТГ (кардиотокография) - запись сердцебиения малыша и тонуса матки"},{"number":31,"startIndex":2749,"text":"💕 Это все обязательно для всех поступающих на роды для определения дальнейшей тактики. "},{"number":32,"startIndex":2838,"text":"💕 Как только оформление завершено, вас сопровождает персонал в родовой блок. Если ваш партнер приехал с вами, то вместе с партнером. "},{"number":33,"startIndex":2973,"text":"✨ Если вы приехали по записи в отделение патологии беременных:"},{"number":34,"startIndex":3036,"text":"✅В приёмном покое вас встречают, оформляют документы"},{"number":35,"startIndex":3089,"text":"✅Проверяют направление и назначения"},{"number":36,"startIndex":3125,"text":"✅Заполняют историю"},{"number":37,"startIndex":3144,"text":"✅Проводят первичный осмотр (измерение давления, взвешивание, осмотр акушером)"},{"number":38,"startIndex":3222,"text":"✅Сопровождают в отделение патологии беременных"},{"number":39,"startIndex":3269,"text":"Важно запомнить"},{"number":40,"startIndex":3285,"text":"🔰Приёмное отделение - это не страшно. Это «точка входа». Вас ждут, вам рады, вас готовы принять в любой момент."},{"number":41,"startIndex":3398,"text":"🔰Если вы едете на роды - не ждите до утра. Схватки участились, отошли воды - приезжайте. Даже ночью. Даже в праздник."},{"number":42,"startIndex":3517,"text":"🔰Если вы по записи - приходите строго в назначенное время. Так мы сможем организовать процесс быстро и по времени."},{"number":43,"startIndex":3633,"text":"🔰Партнёру - не забыть флюорографию и сменную одежду. Это единственное, что может помешать быть рядом."}]}},"R10":{"route":{"id":"R10","title":"Отделения патологии беременных","url":"/departments/pregnancy-pathology/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/pregnancy-pathology.json","sourceEditorialPath":"content/sources/pregnancy-pathology.json","editorialPath":"content/editable/r10.json","enabled":true},"source":{"code":"R10","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.hpfgrhm0hf0o","originalUrl":"https://docs.google.com/document/d/1XyHxGzoPFvoWWgp4xBAnO2-qSGM5mUzqxZLPqqCuZPc/edit","paragraphCount":25,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. List markers retained.","review":"Leading literal 0 retained; beds and rooms apply to pregnancy pathology only, not R12/R30.","lines":[{"number":1,"startIndex":309,"text":"0Отделение патологии беременных занимает 4 этаж родильного дома и рассчитано на 30 коек, среди которых 25 предназначены для круглосуточного стационара, а 5 – для дневного."},{"number":2,"startIndex":481,"text":"Основная цель работы отделения – благоприятный исход наступившей беременности. Для этого медицинский персонал ведет грамотное наблюдение за будущими мамами на всех этапах, разрабатывает план ведения беременности и стремится к тому, чтобы ребенок родился здоровым, а здоровье женщины при этом сохранилось."},{"number":3,"startIndex":786,"text":"Помощь в отделении оказывается не только жительницам Пушкинского района, но и женщинам из соседних муниципальных образований Московской области, а также из Москвы, Владимирской и Ярославской областей. За год здесь проходят лечение порядка 2 500 беременных, и примерно 1 200 из них готовятся к родам и затем переводятся в родовое отделение."},{"number":4,"startIndex":1126,"text":"Отделение специализируется на оказании высококвалифицированной медицинской помощи беременным с тяжелой акушерской и перинатальной патологией, начиная с 22 недель беременности. Кроме того, пациентки могут получить помощь медицинского психолога."},{"number":5,"startIndex":1370,"text":"Для комфортного пребывания будущих мам оборудованы палаты разного типа: одноместные повышенной комфортности (люкс и полулюкс), двух-, трех- и четырехместные. Каждая палата имеет душ и туалет. В холле отделения есть телевизор, библиотека, удобные диваны и живой уголок."},{"number":6,"startIndex":1639,"text":"Высокотехнологичное оснащение и квалифицированные специалисты позволяют справляться с самыми разными патологиями. В отделении имеются аппарат УЗИ экспертного класса, аппараты КТГ, аппарат ЭКГ, физиотерапевтический кабинет и комната психологической разгрузки."},{"number":7,"startIndex":1898,"text":"Поскольку родильный дом находится при многопрофильной больнице, у пациенток есть возможность проконсультироваться с врачом любого профиля — хирургом, урологом, нефрологом, нейрохирургом, неврологом, окулистом, аллергологом и другими, а также пройти дополнительные обследования: ЭХО-КГ, компьютерную томографию, магнитно-резонансную томографию, гастроскопию, рентген и другие."},{"number":8,"startIndex":2274,"text":"В штате отделения трудятся врачи высшей и первой квалификационной категории, специалисты ультразвуковой диагностики, а также доброжелательный и квалифицированный средний и младший медицинский персонал."},{"number":9,"startIndex":2476,"text":"С федеральными законами и иными нормативными документами, в соответствии с которыми учреждение ведет свою деятельность, можно ознакомиться в разделе «Нормативные документы»."},{"number":10,"startIndex":2650,"text":"Заведующая отдалением патологии беременных – Данелян Жанна Владиславовна, врач–акушер-гинеколог высшей квалификационной категории"},{"number":11,"startIndex":2780,"text":"Старшая акушерка – Четверикова Анастасия Евгеньевна"},{"number":12,"startIndex":2832,"text":"Врачи отделения:"},{"number":13,"startIndex":2849,"text":"Антипова Наталья Николаевна – врач–акушер-гинеколог высшей квалификационной категории"},{"number":14,"startIndex":2935,"text":"Малькова Наталья Борисовна – врач–акушер-гинеколог высшей квалификационной категории"},{"number":15,"startIndex":3020,"text":"Мирошниченко Александра Сергеевна – врач–акушер-гинеколог высшей квалификационной категории"},{"number":16,"startIndex":3112,"text":"Нерубайло Ольга Ивановна – врач–акушер-гинеколог "},{"number":17,"startIndex":3162,"text":"Хусейнова Оксана Владимировна – врач–акушер-гинеколог первой категории, врач УЗД."},{"number":18,"startIndex":3244,"text":"Пост:"},{"number":19,"startIndex":3250,"text":" 8 (496) 539-30-70 доб. 4014"},{"number":20,"startIndex":3279,"text":" "},{"number":21,"startIndex":3281,"text":"Часы приема врачами родственников пациентов:"},{"number":22,"startIndex":3326,"text":"В будние дни:"},{"number":23,"startIndex":3340,"text":"14:00-15:00"},{"number":24,"startIndex":3352,"text":"Выписка:"},{"number":25,"startIndex":3361,"text":"13:00-19:00"}]}},"R13":{"route":{"id":"R13","title":"Отделение физиологии новорожденных","url":"/departments/newborn-care/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/newborn-care.json","sourceEditorialPath":"content/sources/newborn-care.json","editorialPath":"content/editable/r13.json","enabled":true},"source":{"code":"R13","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.srs24o45psdl","originalUrl":"https://docs.google.com/document/d/1ihkdudgTsfhIj8OPNliCa8Q5rMqLIXpFlBdQCcqtZVE/edit","paragraphCount":31,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. List markers retained.","review":"U+000B staff separators retained raw; all four names displayed on separate lines.","lines":[{"number":1,"startIndex":286,"text":"Отделение физиологии новорождённых – небольшое и является частью послеродового отделения. Так сложилось потому, что практически все дети находятся на совместном пребывании с мамами. В отделении наблюдаются малыши лишь в нескольких случаях: если роды прошли путём кесарева сечения и мама после операции ещё не переведена в послеродовое отделение, а находится в отделении реанимации и интенсивной терапии; или если мама сама попросила взять малыша на несколько часов, чтобы немного отдохнуть и восстановиться после родов."},{"number":2,"startIndex":806,"text":"В отделении новорождённых, через которое за год проходит около 2 000 малышей, есть всё необходимое для периода адаптации: открытая реанимационная система DRAGER, лампы фототерапии, аппарат УЗИ, кроватки с подогревом для маловесных и незрелых детей, одноразовые расходные материалы. Помощь малышам оказывается с учётом новых перинатальных технологий и методик."},{"number":3,"startIndex":1166,"text":"Отделение осуществляет следующие функции:"},{"number":4,"startIndex":1208,"text":"- уход за новорождёнными, которые находятся в отделении;"},{"number":5,"startIndex":1265,"text":"- обеспечение совместного пребывания мамы и малыша;"},{"number":6,"startIndex":1317,"text":"- поддержка грудного вскармливания;"},{"number":7,"startIndex":1353,"text":"- проведение лечебно-профилактические мероприятий, включая первичную реанимацию в родильном зале;"},{"number":8,"startIndex":1451,"text":"- контроль за санитарно-противоэпидемическим режимом;"},{"number":9,"startIndex":1505,"text":"- проведение санитарно-просветительской работы с мамами и родственниками;"},{"number":10,"startIndex":1579,"text":"- проведение неонатального, кардиологического и аудиологического скрининга;"},{"number":11,"startIndex":1655,"text":"- проведение вакцинации новорождённых;"},{"number":12,"startIndex":1694,"text":"Помощь здесь оказывают профилактическую и лечебно-консультативную в объёме неонатального профиля родильного дома."},{"number":13,"startIndex":1808,"text":"Диагностические возможности отделения:"},{"number":14,"startIndex":1847,"text":"- консультации специалистов;"},{"number":15,"startIndex":1876,"text":"- лабораторные обследования – анализы крови и мочи, биохимия;"},{"number":16,"startIndex":1938,"text":"- микробиологические исследования;"},{"number":17,"startIndex":1973,"text":"- коагулограмма;"},{"number":18,"startIndex":1990,"text":"- УЗИ внутренних органов и головного мозга;"},{"number":19,"startIndex":2034,"text":"- ЭХО-КГ;"},{"number":20,"startIndex":2044,"text":"- рентгенологическое обследование."},{"number":21,"startIndex":2079,"text":"Так же в отделении работает волонтёрская служба консультантов по грудному вскармливанию. Они приходят три раза в неделю и помогают женщинам по всем вопросам ГВ – наладить лактацию, справиться с трудностями и сохранить грудное вскармливание. Это живое, человеческое участие, которое особенно важно для мам в непростой период."},{"number":22,"startIndex":2404,"text":"С федеральными законами и иными нормативными документами, в соответствии с которыми учреждение осуществляет свою деятельность, можно ознакомиться в разделе «Нормативные документы»."},{"number":23,"startIndex":2585,"text":"Заведующая отделением – Кудрявцева Дарья Валерьевна, врач-неонатолог первой квалификационной категории"},{"number":24,"startIndex":2688,"text":"Старшая медицинская сестра отделения – Жукова Юлия Сергеевна"},{"number":25,"startIndex":2749,"text":"Врачи отделения:"},{"number":26,"startIndex":2766,"text":"Галуза Ирина Валентиновна – врач-неонатолог первой квалификационной категории"},{"number":27,"startIndex":2844,"text":"Захарова Татьяна Васильевна – врач-неонатолог высшей квалификационной категории\u000bКоролева Екатерина Сергеевна – врач-неонатолог второй квалификационной категории\u000bМихеева Елена Владимировна – врач-неонатолог высшей квалификационной категории\u000bСюняева Марина Александровна – врач-неонатолог "},{"number":28,"startIndex":3132,"text":"Пост:"},{"number":29,"startIndex":3138,"text":"8 (496) 539-30-70 доб. 4010"},{"number":30,"startIndex":3166,"text":" "},{"number":31,"startIndex":3168,"text":" Беседа с родителями врача-неонатолога в будние дни: с 11:00-12:00"}]}},"R14":{"route":{"id":"R14","title":"Отделение реанимации беременных, родильниц и рожениц","url":"/departments/maternal-intensive-care/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/maternal-intensive-care.json","sourceEditorialPath":"content/sources/maternal-intensive-care.json","editorialPath":"content/editable/r14.json","enabled":true},"source":{"code":"R14","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.nzudlqxdben0","compositionTabId":"t.5ss7lz8h59ar","originalUrl":"https://docs.google.com/document/d/1-vZhhbLpvwRhCIzeR94ET2xqoEjEQz8h5rEH2KR8n1U/edit","paragraphCount":34,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. Original glyphs and list markers retained.","review":"Qualification fragment at paragraph 20 remains standalone. Normative/head paragraph 19 and team paragraphs 21/24 contain U+000B. Staffing, intensive-care and anesthesia claims, relatives' discussion rules, extensions 4025/4023 require institutional verification.","lines":[{"number":1,"startIndex":309,"text":"Отделение входит в состав Центра анестезиологии-реанимации и обеспечивает круглосуточную анестезиологическую и реанимационную помощь по акушерскому профилю. Здесь находятся беременные, роженицы и родильницы с сопутствующей экстрагенитальной патологией, нуждающиеся в интенсивной терапии и наблюдении и относящиеся к высокой группе риска."},{"number":2,"startIndex":647,"text":"На одном этаже с родовым блоком и оперблоком расположены две двухместные и две одноместные реанимационные палаты. Они оснащены современными многофункциональными кроватями, консолями с подводкой кислорода и аппаратурой экспертного класса."},{"number":3,"startIndex":885,"text":"Отделение специализируется на:"},{"number":4,"startIndex":916,"text":"- проведении интенсивной терапии и реанимационных мероприятий на территории родильного дома, плановых и экстренных анестезиологических пособий любой сложности, консультативном осмотре пациенток в отделениях родильного дома;"},{"number":5,"startIndex":1140,"text":"- оценке риска анестезиологического пособия у пациентов с отягощённым анамнезом и выборе оптимального метода анестезии;"},{"number":6,"startIndex":1260,"text":"- оказании всех видов анестезиологического пособия (комбинированная эндотрахеальная, спинномозговая, эпидуральная, тотальная внутривенная анестезия) у пациентов с сопутствующей травматологической, гинекологической, урологической, нейрохирургической, офтальмологической патологией;"},{"number":7,"startIndex":1541,"text":"- ведении пациентов в послеоперационном периоде и лечении жизнеугрожающих состояний (преэклампсия, HELLP-синдром, полиорганная недостаточность, сепсис, жизнеугрожающие нарушения сердечного ритма и другие)."},{"number":8,"startIndex":1747,"text":"Все родильницы после кесарева сечения направляются в отделение анестезиологии-реанимации для интенсивного мониторинга и обезболивания, где находятся под наблюдением врача анестезиолога-реаниматолога."},{"number":9,"startIndex":1947,"text":"В родильном доме работают три большие операционные. Каждая оснащена современным наркозно-дыхательным аппаратом, медицинским аспиратором, дефибриллятором, шприцевым дозатором, монитором слежения и набором препаратов для анестезии и интенсивной терапии. В операционных установлены консоли с кислородной подводкой для наркозно-дыхательной аппаратуры и полки для размещения анестезиологического оборудования. В экстренной ситуации операционные разворачиваются за считанные секунды — ведь речь идёт о жизни и здоровье двух человек."},{"number":10,"startIndex":2474,"text":"Врачи отделения владеют всеми видами анестезии и интенсивной терапии. Для анестезии используются только современные и безопасные медикаменты. Интенсивная терапия и анестезиологическое обеспечение осуществляются в соответствии с рекомендациями Федерации анестезиологов и реаниматологов РФ. Предстоящую анестезию можно обсудить с врачом-анестезиологом, который расскажет о преимуществах и недостатках разных видов обезболивания и порекомендует наиболее оптимальный и безопасный метод."},{"number":11,"startIndex":2957,"text":"Для обезболивания самопроизвольных родов широко применяется эпидуральная анальгезия. При отсутствии противопоказаний, таких как гипокоагуляция, тромбоцитопения, сепсис и некоторых других состояний, она может быть выполнена большинству женщин. В современных условиях это довольно безопасный и эффективный метод с крайне низкой частотой осложнений. Перед процедурой роженице внутривенно вводится физиологический раствор, кожа обрабатывается антисептиком, выполняется местное обезболивание. Затем в эпидуральное пространство устанавливается тонкий катетер, через который обезболивающие препараты вводятся по потребности или непрерывно с помощью шприца-дозатора. Во время процедуры регулярно измеряется артериальное давление, а анестезиолог проверяет действенность анальгезии. Обычно эффект наступает примерно через 15 минут."},{"number":12,"startIndex":3779,"text":"При плановом кесаревом сечении основными видами обезболивания являются нейроаксиальные методы анестезии – спинальная, эпидуральная и спинально-эпидуральная. Наиболее распространена спинальная анестезия. Не стоит бояться и общей анестезии: современная анестезиология позволяет минимизировать связанные с ней риски. Эндотрахеальный наркоз применяется, когда регионарная анестезия противопоказана. Внутривенная анестезия используется в основном в послеродовом периоде при ушивании разрывов мягких тканей и ручном обследовании полости матки."},{"number":13,"startIndex":4317,"text":"Отделение реанимации для беременных, рожениц и родильниц оснащено современными средствами ухода за тяжёлыми больными, а медицинский персонал специально подготовлен для проведения ухода и реанимационных мероприятий в любом необходимом объёме."},{"number":14,"startIndex":4559,"text":"Помимо анестезиологической работы, здесь оказывается интенсивная терапия при жизнеугрожающих состояниях. Всем послеоперационным пациенткам проводится клинико-лабораторный мониторинг в отделении реанимации в ближайшие часы послеоперационного периода."},{"number":15,"startIndex":4809,"text":"Применение современных технологий, инструментов и шовных материалов обеспечивает минимальную инвазивность и предотвращает тяжёлые послеоперационные осложнения. Имеется аппарат Cell-saver для сбора и переливания собственной крови пациентки; все врачи отделения владеют навыками работы с ним."},{"number":16,"startIndex":5100,"text":"Проводится коррекция нарушений гемостаза у пациенток акушерского профиля с применением уникального российского оборудования. С 2017 года используется диагностическая лабораторная система «Регистратор тромбодинамики». Тест тромбодинамики — универсальный анализ системы свёртывания крови, дающий интегральную картину происходящих изменений и учитывающий все возможные факторы влияния. Методика позволяет сократить число неразвивающихся беременностей и недоношенных детей, рождённых с экстремально низкой массой тела. В близлежащих районах Московской области подобной аппаратуры нет."},{"number":17,"startIndex":5681,"text":"Диагностические возможности отделения включают полное клинико-лабораторное обследование, ЭХО-КГ, рентген, УЗИ, ЭКГ, КТ, а также консультации терапевта, кардиолога, невролога, офтальмолога, уролога, нефролога, хирурга, травматолога, нейрохирурга и других специалистов при необходимости."},{"number":18,"startIndex":5967,"text":"В интересах отделения круглосуточно работает лаборатория экстренных исследований. При необходимости ряд исследований можно провести непосредственно в отделении реанимации, как и получить консультации врачей других специальностей."},{"number":19,"startIndex":6197,"text":"С федеральными законами и иными нормативными документами, в соответствии с которыми учреждение осуществляет свою деятельность, можно ознакомиться в разделе «Нормативные документы».\u000b\u000bЗаведующий отделением – Козиев Михаил Петрович, кандидат медицинских наук;"},{"number":20,"startIndex":6454,"text":"высшая квалификационная категория по специальности «Анестезиология и реаниматология»"},{"number":21,"startIndex":6539,"text":"Старшая медицинская сестра отделения – Краева Людмила Алексеевна\u000b\u000bВрачи отделения:"},{"number":22,"startIndex":6622,"text":"Джураев Абдурайим Абдулилович – врач–анестезиолог-реаниматолог"},{"number":23,"startIndex":6685,"text":"Кармышев Артур Наильевич – врач–анестезиолог-реаниматолог"},{"number":24,"startIndex":6743,"text":"Карнов Дмитрий Владимирович – врач–анестезиолог-реаниматолог\u000bКокляева Наталья Вадимовна – врач–анестезиолог-реаниматолог"},{"number":25,"startIndex":6864,"text":"Окилов Григорий Юрьевич ­– врач–анестезиолог-реаниматолог"},{"number":26,"startIndex":6922,"text":"Харченко Елена Николаевна – врач–анестезиолог-реаниматолог "},{"number":27,"startIndex":6982,"text":"Ординаторская:"},{"number":28,"startIndex":6997,"text":" 8 (496) 539-30-70 доб. 4025"},{"number":29,"startIndex":7026,"text":"Пост:"},{"number":30,"startIndex":7032,"text":" 8 (496) 539-30-70 доб. 4023"},{"number":31,"startIndex":7061,"text":" "},{"number":32,"startIndex":7063,"text":"Часы приема врачами родственников пациентов:"},{"number":33,"startIndex":7108,"text":"В будние дни с 11:00 до 16:00 – заведующий отделением"},{"number":34,"startIndex":7162,"text":"В выходные и праздничные дни с 11:00 до 16:00 – дежурный врач-реаниматолог "}]}},"R15":{"route":{"id":"R15","title":"Отделение реанимации и интенсивной терапии новорожденных","url":"/departments/neonatal-intensive-care/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/neonatal-intensive-care.json","sourceEditorialPath":"content/sources/neonatal-intensive-care.json","editorialPath":"content/editable/r15.json","enabled":true},"source":{"code":"R15","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.nx4nqbgcgt43","compositionTabId":"t.m0xai0r8zce3","originalUrl":"https://docs.google.com/document/d/1B2ssrv1TyuOf8QzjRCt9QLhZenYkoLTbype-pHKhjNQ/edit","paragraphCount":51,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. Original glyphs and list markers retained.","review":"Unrestricted parental access narrative and specific mother/father/relative schedules both retained; no editorial reconciliation. U+000B in paragraphs 43/46/47/50/51. Clinical claims, personnel, admission pathways, access hours and extension 4028 require institutional verification.","lines":[{"number":1,"startIndex":309,"text":"Отделение реанимации и интенсивной терапии новорождённых – это 6 реанимационных коек, две из которых предназначены для совместного пребывания мамы и малыша. Отделение расположено на 4 этаже родильного дома и входит в состав Центра анестезиологии-реанимации."},{"number":2,"startIndex":567,"text":"В отделении оказывается реанимационная помощь и интенсивная терапия патологических состояний у новорождённых и недоношенных детей. Малыши, которым предстоит длительное лечение, госпитализируются вместе с мамами – они не разлучаются ни на день. Для этого созданы специальные места совместного пребывания."},{"number":3,"startIndex":871,"text":"Ежегодно через отделение проходят около 300 новорождённых. Среди патологий, с которыми здесь работают:"},{"number":4,"startIndex":974,"text":"- респираторные нарушения;"},{"number":5,"startIndex":1001,"text":"- врождённые инфекционные болезни;"},{"number":6,"startIndex":1036,"text":"- перинатальные повреждения ЦНС;"},{"number":7,"startIndex":1069,"text":"- гемолитическая болезнь младенцев;"},{"number":8,"startIndex":1105,"text":"- гипербилирубинемии новорождённых различного генеза;"},{"number":9,"startIndex":1159,"text":"- эндокринные заболевания;"},{"number":10,"startIndex":1186,"text":"- врождённые аномалии развития и генетические синдромы."},{"number":11,"startIndex":1242,"text":"Отделение располагает всем необходимым – и квалифицированным персоналом, и специализированным оборудованием – для оказания полного спектра высокотехнологичной медицинской помощи. Здесь обеспечивают искусственную вентиляцию лёгких, клиническую стабилизацию тяжелобольных и недоношенных детей."},{"number":12,"startIndex":1534,"text":"Врачи отделения оказывают новорождённым:"},{"number":13,"startIndex":1575,"text":"- первичную реанимационную помощь в родильном зале со стабилизацией состояния и последующим переводом в отделение;"},{"number":14,"startIndex":1690,"text":"- респираторную стабилизацию – ранний СРАР, ИВЛ инвазивным и неинвазивным методом;"},{"number":15,"startIndex":1773,"text":"- терапию сурфактантом;"},{"number":16,"startIndex":1797,"text":"- мониторинг оксигенации крови и адекватности оксигенотерапии недоношенных с момента рождения;"},{"number":17,"startIndex":1892,"text":"- кардиореанимацию – непрямой массаж сердца, введение адреналина, атропина, экстренную коррекцию КЩС, восполнение ОЦК."},{"number":18,"startIndex":2011,"text":"После стабилизации в родильном зале пациента транспортируют в отделение в транспортном кувезе. При хирургической патологии, требующей экстренной или отсроченной помощи, проводится стабилизация с последующей транспортировкой в профильное учреждение."},{"number":19,"startIndex":2260,"text":"Вся медицинская техника в отделении соответствует современным требованиям выхаживания новорождённых. Здесь есть:"},{"number":20,"startIndex":2373,"text":"- современные инкубаторы для выхаживания недоношенных деток с экстремальной и очень низкой массой тела, обеспечивающие оптимальный уровень температуры и влажности;"},{"number":21,"startIndex":2537,"text":"- открытые реанимационные столы с системой сервоконтроля;"},{"number":22,"startIndex":2595,"text":"- мониторы слежения за витальными показателями;"},{"number":23,"startIndex":2643,"text":"- современные аппараты для поддержки дыхания у новорождённых любой категории сложности;"},{"number":24,"startIndex":2731,"text":"- анализатор газов крови, параметров оксиметрии, электролитов и метаболитов;"},{"number":25,"startIndex":2808,"text":"- современный цифровой передвижной портативный рентгенографический аппарат;"},{"number":26,"startIndex":2884,"text":"- электроэнцефалограф для ЭЭГ-мониторинга;"},{"number":27,"startIndex":2927,"text":"- церебральный оксиметр, позволяющий неинвазивно и непрерывно оценивать насыщение гемоглобина кислородом в крови церебральных венозных сосудов;"},{"number":28,"startIndex":3071,"text":"- современные лампы фототерапии."},{"number":29,"startIndex":3104,"text":"Новорождённые находятся в условиях открытой реанимационной системы или в кувезе, где создаются максимально комфортные условия для выхаживания. Для длительной инфузионной терапии, инотропной и вазопрессорной поддержки, частого забора крови, частичного или полного парентерального питания устанавливаются один или два центральных катетера по методу Сельдингера или глубокая венозная линия. Проводится продлённая инвазивная респираторная терапия в режимах nСРАР, IMV, SIMV, IPPV, HFO. Применяются технология ингаляции оксида азота, мониторинг ЭЭГ и церебральной перфузии."},{"number":30,"startIndex":3673,"text":"Ведётся динамический мониторинг кислотно-щелочного и газового состояния крови, витальных функций организма, физикальный осмотр. Ежедневно пересчитывается инфузионная терапия с учётом веса, возраста, общего состояния, течения заболевания, суточной потребности в жидкости и нутриентах. Все манипуляции проводятся со строжайшим соблюдением правил асептики и антисептики."},{"number":31,"startIndex":4041,"text":"Диагностические возможности отделения:"},{"number":32,"startIndex":4080,"text":"- биохимические исследования;"},{"number":33,"startIndex":4110,"text":"- общеклинический анализ крови и мочи;"},{"number":34,"startIndex":4149,"text":"- определение группы крови, резус- и Келл-факторов;"},{"number":35,"startIndex":4201,"text":"- современные методы клинической лабораторной диагностики инфекционных заболеваний (ИФА, ПЦР);"},{"number":36,"startIndex":4296,"text":"- неонатальный скрининг для раннего выявления наследственных заболеваний;"},{"number":37,"startIndex":4370,"text":"- круглосуточная рентгенодиагностика;"},{"number":38,"startIndex":4408,"text":"- УЗИ головного мозга, сердца, органов брюшной полости, почек;"},{"number":39,"startIndex":4471,"text":"- консультации специалистов — окулиста, невролога, кардиолога, хирурга."},{"number":40,"startIndex":4543,"text":"В отделение принимаются дети из родильного зала, отделения физиологии новорождённых, отделения патологии новорождённых и недоношенных детей, после домашних родов."},{"number":41,"startIndex":4706,"text":"Но главная особенность отделения – это то, что родители имеют беспрепятственный доступ к своим детям. В отделении созданы все условия для поддержки грудного вскармливания. А мамы, чьи дети находятся в реанимации на длительном лечении, могут круглосуточно оставаться рядом с ними – для этого предусмотрены два специально оборудованные палаты совместного пребывания."},{"number":42,"startIndex":5071,"text":"С федеральными законами и иными нормативными документами, в соответствии с которыми учреждение осуществляет свою деятельность, можно ознакомиться в разделе «Нормативные документы»."},{"number":43,"startIndex":5252,"text":"Заведующая отделением – Лоскутова Евгения Викторовна, врач высшей квалификационной категории по специальности «Анестезиология и реаниматология»\u000b"},{"number":44,"startIndex":5397,"text":"Старшая медсестра отделения – Ащеульникова Ольга Владимировна"},{"number":45,"startIndex":5459,"text":"Врачи отделения:"},{"number":46,"startIndex":5476,"text":"Опренко Наала Аслановна – врач–анестезиолог-реаниматолог высшей квалификационной категории\u000bОпренко Артем Александрович – врач–анестезиолог-реаниматолог высшей квалификационной категории"},{"number":47,"startIndex":5662,"text":"Романова Анна Сергеевна – врач–анестезиолог-реаниматолог первой квалификационной категории\u000bСавченко Иван Владимирович – врач–анестезиолог-реаниматолог высшей квалификационной категории\u000b\u000b"},{"number":48,"startIndex":5849,"text":"Пост:"},{"number":49,"startIndex":5855,"text":" 8 (496) 539-30-70 доб. 4028"},{"number":50,"startIndex":5884,"text":"\u000bВремя посещения: для мам – круглосуточно, для пап и других родственников – с 09:00 до 18:00, пропускная система"},{"number":51,"startIndex":5997,"text":"Беседа с родственниками заведующего отделением – с 14:00 до 16:00 в рабочие дни. \u000bВ выходные и праздничные дни сведения предоставляет дежурный реаниматолог с 14:00-15:00"}]}},"R16":{"route":{"id":"R16","title":"Отделение патологии новорожденных","url":"/departments/neonatal-pathology/","type":"T4","adapter":"numbered-lines","sourcePath":"src/data/sources/neonatal-pathology.json","sourceEditorialPath":"content/sources/neonatal-pathology.json","editorialPath":"content/editable/r16.json","enabled":true},"source":{"code":"R16","documentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","revisionId":"AHj4eMTGgDtB6bEFMnPpvklqGvmZ6scT18OD25CRIO_9TdAvTGfjaZSVZWnQlnWoAy6D8dnHVpWaUF4vcneEipPlHcmqCKwkdQ-8p753oGI","tabId":"t.ikw2etad4ir1","compositionTabId":"t.bvc2cnr9brlo","originalUrl":"https://docs.google.com/document/d/1h0Srf1U3IeHIcvR9y24WxjcQ5OqboRKh7YBMwzXTWd8/edit","paragraphCount":30,"status":"STRUCTURE / PROPOSED / NOT OWNER-APPROVED","verification":"Authored medical, organizational, staffing, contact and schedule claims preserved without factual verification; releaseReady=false","transforms":"Raw text unchanged. Whitespace-only paragraphs omitted from DOM. U+000B displayed as newline with pre-line. Original glyphs and list markers retained.","review":"Unusual qualification wording in paragraph 23 retained. Blank paragraphs 24/29 retained raw. Paragraph 30 U+000B separates discussion and discharge schedules; both displayed. Diagnostics, treatments, rehabilitation, family support, personnel, hours and extensions 3000/3001 require institutional verification.","lines":[{"number":1,"startIndex":309,"text":"Отделение патологии новорождённых и недоношенных детей – это современное отделение, где проводят диагностику, лечение и выхаживание малышей, в том числе с низкой массой тела. Отделение работает по принципу круглосуточного совместного пребывания матери и ребёнка: здесь оборудованы боксы повышенной комфортности и собрана новейшая техника, позволяющая выхаживать детей, родившихся с низкой массой тела и различными перинатальными патологиями."},{"number":2,"startIndex":751,"text":"Сюда госпитализируют как в экстренном, так и в плановом порядке – и детей, родившихся в нашем Перинатальном центре, и малышей из других родильных домов Москвы и Московской области при наличии профильной патологии и неонатального возраста."},{"number":3,"startIndex":990,"text":"Отделение оказывает специализированную неонатальную помощь новорождённым и недоношенным детям любой категории, кроме хирургической. Здесь занимаются постреанимационной реабилитацией доношенных и недоношенных детей, их лечением и выхаживанием."},{"number":4,"startIndex":1233,"text":"При поступлении ребёнку проводится комплексное обследование. Диагностические возможности отделения включают:"},{"number":5,"startIndex":1342,"text":"лабораторное обследование – клинический анализ крови и мочи, биохимический анализ крови и мочи, кислотно-основное состояние;"},{"number":6,"startIndex":1467,"text":"микробиологическое исследование;"},{"number":7,"startIndex":1500,"text":"коагулограмму;"},{"number":8,"startIndex":1515,"text":"отоакустическую эмиссию;"},{"number":9,"startIndex":1540,"text":"УЗИ внутренних органов и головного мозга (нейросонографию);"},{"number":10,"startIndex":1600,"text":"ЭХО-КГ, электроэнцефалографию;"},{"number":11,"startIndex":1631,"text":"рентгенологическое обследование грудной клетки и брюшной полости по показаниям, в том числе с контрастом;"},{"number":12,"startIndex":1737,"text":"осмотры специалистов – отоларинголога, невролога, окулиста; при необходимости для консультации вызываются кардиолог, генетик, нейрохирург из специализированных лечебных учреждений."},{"number":13,"startIndex":1918,"text":"Комплексное обследование позволяет в ранние сроки поставить правильный диагноз и вовремя начать терапию: патогенетически обоснованную инфузионную терапию, антибиотики широкого спектра действия и резерва, препараты, улучшающие микроциркуляцию и обменные процессы в нервных клетках, стимуляторы эритропоэза и другие средства."},{"number":14,"startIndex":2242,"text":"В отделении регулярно проводятся мероприятия по грудному вскармливанию, мам обучают уходу за новорождённым и недоношенным ребёнком. При отсутствии противопоказаний проводится вакцинация новорождённых ( в том числе в отделении осуществляется профилактическая иммунизация от РСВ-инфекций новорожденным на 35 неделе и ранее), осуществляются консультации детей до 3 месяцев в отделении соматического профиля, проводятся неонатальный, кардиологический и аудиологический скрининги. В лечении используются физиотерапевтические методы – плавание, водные процедуры, лечебный и профилактический массаж."},{"number":15,"startIndex":2835,"text":"Через заботливые руки персонала за год проходят до 600 детей с различной перинатальной патологией. Благодаря профессионализму и опыту медицинского персонала сотням матерей подарено счастье видеть улыбки и успехи своих детей."},{"number":16,"startIndex":3060,"text":"С федеральными законами и иными нормативными документами, в соответствии с которыми учреждение осуществляет свою деятельность, можно ознакомиться в разделе «Нормативные документы»."},{"number":17,"startIndex":3241,"text":"Заведующая отделением – Бокова Оксана Васильевна, врач-неонатолог высшей квалификационной категории"},{"number":18,"startIndex":3341,"text":"Старшая медицинская сестра – Белова Светлана Анатольевна"},{"number":19,"startIndex":3398,"text":"Врачи отделения:"},{"number":20,"startIndex":3415,"text":"Кудряшова Юлия Юрьевна – врач-окулист"},{"number":21,"startIndex":3453,"text":"Мирохина Людмила Леонидовна – врач-невролог"},{"number":22,"startIndex":3497,"text":"Недбайлова Татьяна Анатольевна – врач-неонатолог "},{"number":23,"startIndex":3547,"text":"Шалеева Наталья Владимировна – врач-неонатолог высшей квалификационной патологии"},{"number":24,"startIndex":3628,"text":" "},{"number":25,"startIndex":3630,"text":"Ординаторская:"},{"number":26,"startIndex":3645,"text":" 8 (496) 539-30-70 доб. 3000"},{"number":27,"startIndex":3674,"text":"Пост:"},{"number":28,"startIndex":3680,"text":" 8 (496) 539-30-70 доб. 3001"},{"number":29,"startIndex":3709,"text":" "},{"number":30,"startIndex":3711,"text":"Беседа с родителями: с 14:00 до 16:00 в будние дни\u000bВыписка: с 14:00 до 19:00"}]}},"R29":{"route":{"id":"R29","title":"Контрактные роды","url":"/services/contract-birth/","type":"T7","adapter":"string-lines","sourcePath":"src/data/sources/contract-birth.json","sourceEditorialPath":"content/sources/contract-birth.json","editorialPath":"content/editable/r29.json","enabled":true},"source":{"origin":"https://prbmo.ru/perinatalnyj-tsentr/programmy-vedeniya-kontraktnykh-rodov","derivedDocumentId":"1uKy3KHRXn1IlxfHs4Vmzm9l97VARntRx5yYzm0YWbvQ","copyDocumentId":"1qMaqjuRXSlQ97yUaLwFcC1Cmu9YAo7n0kZ9kH9ZiCAQ","tabId":"t.kb4wekls4us9","status":"OWNER-ACCEPTED WORKING COMPOSITION; historical derived pack; not Guzel original; verify before publication","paragraphs":["10. Контрактные роды и платные программы","На сайте есть отдельный раздел программ ведения контрактных родов.","Перед заключением контракта описана возможность предварительной консультации, обсуждения плана родов и выбора программы.","Опубликованы три уровня программ для физиологических родов:","Standard — 95 100 ₽.","Comfort — 100 700 ₽.","Premium — 125 700 ₽.","Standard включает роды с дежурным врачом в индивидуальном родовом зале, необходимое медицинское наблюдение и обследования, работу дежурной бригады, лабораторные исследования, КТГ/УЗИ/допплерометрию по показаниям, одноместную послеродовую палату и пребывание в рамках программы. Также предусмотрены обезболивание по показаниям и возможность партнёрских родов.","Comfort предусматривает выбор врача, возможность связи с выбранным врачом, ведение родов выбранным врачом совместно с акушеркой, индивидуальный родовый зал и одноместную палату. На странице отдельно указана возможность индивидуальной акушерки за дополнительную стоимость 35 000 ₽. Итоговая стоимость может уточняться после консультации.","Premium предусматривает ведение родов руководителем/ведущим специалистом программы, индивидуальный родовый зал и одноместное размещение после родов. На странице в связи с премиальной программой фигурируют Андрей Леонардович Лесной, Жанна Владиславовна Данелян и А. В. Мох.","Для кесарева сечения опубликованы три программы:","Standard — 115 600 ₽.","Comfort — 121 200 ₽.","Premium — 143 200 ₽.","В программах кесарева сечения описаны операция дежурным либо выбранным врачом в зависимости от тарифа, лабораторные и инструментальные исследования, анестезиологическое обеспечение, послеоперационное наблюдение и размещение. Для Comfort описаны спинальная/общая анестезия и TAP-блок по показаниям, а также выбор врача. Для Premium операция проводится руководителем/ведущим специалистом программы.","Продолжительность пребывания в платных программах зависит от вида родоразрешения и конкретного тарифа. Для кесарева сечения на странице фигурирует пребывание до пяти койко-дней.","Контакты платных услуг:","8 (800) 500-12-75.","mz_prbmo_pmu@mosreg.ru.","Цены, состав программ, список специалистов и условия — динамические сущности. Их необходимо хранить в структуре сайта отдельно от редакционного текста, чтобы обновлять без переписывания страниц."]}}};
